import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path
from typing import Dict, List, Any, Optional, Union

def load_json_file(file_path: Path) -> Any:
    """Load JSON data from a file."""
    with open(file_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def find_award_by_id(awards: List[Dict], award_id: str) -> Optional[Dict]:
    """Find an award by its generated_unique_award_id."""
    for award in awards:
        if award.get('generated_unique_award_id') == award_id:
            return award
    return None

def extract_date(value: Any) -> Optional[str]:
    """Extract and format date from various string formats."""
    if value is None:
        return None
    if isinstance(value, str):
        # Handle date strings that might have time components
        date_part = value.split(' ')[0]
        try:
            # Try parsing common date formats
            for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%m/%d/%Y'):
                try:
                    dt = datetime.strptime(date_part, fmt)
                    return dt.strftime('%Y-%m-%d')
                except ValueError:
                    continue
        except:
            return None
    return None

def extract_amount(value: Any) -> Optional[str]:
    """Extract amount as decimal string."""
    if value is None:
        return None
    if isinstance(value, (int, float)):
        # Format without unnecessary decimal places
        if value == int(value):
            return str(int(value))
        return str(float(value))
    if isinstance(value, str):
        # Try to convert string to number
        try:
            num = float(value)
            if num == int(num):
                return str(int(num))
            return str(num)
        except:
            return None
    return None

def process_period_3y(award: Dict, document_name: str) -> Dict[str, Union[str, List[str]]]:
    """Process period_3y rule facts."""
    result = {}

    # Get period of performance
    period = award.get('period_of_performance', {})

    # Performance start
    start_date = period.get('start_date')
    if start_date:
        formatted_start = extract_date(start_date)
        if formatted_start:
            result['performance start'] = [formatted_start, document_name]
        else:
            result['performance start'] = "ABSENT"
    else:
        result['performance start'] = "ABSENT"

    # Performance end
    end_date = period.get('end_date')
    if end_date:
        formatted_end = extract_date(end_date)
        if formatted_end:
            result['performance end'] = [formatted_end, document_name]
        else:
            result['performance end'] = "ABSENT"
    else:
        result['performance end'] = "ABSENT"

    return result

def process_obligated_95(award: Dict, document_name: str) -> Dict[str, Union[str, List[str]]]:
    """Process obligated_95 rule facts."""
    result = {}

    # Amount obligated
    amount_obligated = award.get('total_obligation')
    if amount_obligated is not None:
        formatted_amount = extract_amount(amount_obligated)
        if formatted_amount:
            result['amount obligated'] = [formatted_amount, document_name]
        else:
            result['amount obligated'] = "ABSENT"
    else:
        result['amount obligated'] = "ABSENT"

    # Potential value
    potential_value = award.get('base_and_all_options')
    if potential_value is not None:
        formatted_potential = extract_amount(potential_value)
        if formatted_potential:
            result['potential value'] = [formatted_potential, document_name]
        else:
            result['potential value'] = "ABSENT"
    else:
        result['potential value'] = "ABSENT"

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = Path(sys.argv[1])
    manifest_path = Path(sys.argv[2])

    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load awards data
    awards_file = packet_dir / "usaspending_awards.json"
    if not awards_file.exists():
        print(f"Error: {awards_file} not found", file=sys.stderr)
        sys.exit(1)

    awards_data = load_json_file(awards_file)
    document_name = "usaspending_awards"  # File name without extension

    # Process each pair
    result = {}

    for pair in manifest['pairs']:
        rule_id, entity = pair.split('::', 1)

        # Find the award
        award = find_award_by_id(awards_data, entity)
        if not award:
            # If award not found, all facts are ABSENT
            fact_names = manifest['facts'][rule_id]
            result[pair] = {fact: "ABSENT" for fact in fact_names}
            continue

        # Process based on rule
        if rule_id == 'usa.period_3y':
            result[pair] = process_period_3y(award, document_name)
        elif rule_id == 'usa.obligated_95':
            result[pair] = process_obligated_95(award, document_name)
        else:
            # Unknown rule, all facts ABSENT
            fact_names = manifest['facts'][rule_id]
            result[pair] = {fact: "ABSENT" for fact in fact_names}

    # Output result as JSON
    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
