import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def load_json_file(file_path):
    """Load and parse a JSON file."""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except (json.JSONDecodeError, FileNotFoundError):
        return None

def extract_fact_from_award(award, fact_name, rule_id):
    """Extract a specific fact from an award based on the rule."""
    if rule_id == "usa.period_3y":
        if fact_name == "performance start":
            value = award.get("period_of_performance", {}).get("start_date")
            return value, "usaspending_awards"
        elif fact_name == "performance end":
            value = award.get("period_of_performance", {}).get("end_date")
            return value, "usaspending_awards"
    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            value = award.get("total_obligation")
            return value, "usaspending_awards"
        elif fact_name == "potential value":
            value = award.get("base_and_all_options")
            return value, "usaspending_awards"
    return None, None

def find_award_by_id(awards, award_id):
    """Find an award by its generated_unique_award_id."""
    for award in awards:
        if award.get("generated_unique_award_id") == award_id:
            return award
    return None

def process_pair(packet_dir, pair, facts, awards_data):
    """Process a single pair (rule_id::entity)."""
    rule_id, entity_id = pair.split("::", 1)
    fact_names = facts.get(rule_id, [])

    result = {}
    award = find_award_by_id(awards_data, entity_id)

    if award is None:
        # Award not found in data
        for fact_name in fact_names:
            result[fact_name] = "ABSENT"
        return result

    # Collect values for each fact
    fact_values = {}
    for fact_name in fact_names:
        value, doc = extract_fact_from_award(award, fact_name, rule_id)
        if value is None:
            fact_values[fact_name] = ("ABSENT", None)
        else:
            fact_values[fact_name] = (value, doc)

    # Check for conflicts (multiple values for same fact from different sources)
    # In this case, each fact comes from only one source per rule, so no conflict
    for fact_name, (value, doc) in fact_values.items():
        if value == "ABSENT":
            result[fact_name] = "ABSENT"
        else:
            # Format the value appropriately
            if isinstance(value, (int, float)):
                # For amounts, convert to string with proper decimal representation
                if value == int(value):
                    formatted_value = str(int(value))
                else:
                    formatted_value = str(value)
            else:
                formatted_value = str(value)
            result[fact_name] = [formatted_value, doc]

    return result

def main(packet_dir, manifest_path):
    # Load manifest
    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts = manifest.get("facts", {})

    # Load awards data
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards_data = load_json_file(awards_file)
    if awards_data is None:
        awards_data = []

    # Process all pairs
    output = {}
    for pair in pairs:
        output[pair] = process_pair(packet_dir, pair, facts, awards_data)

    # Print JSON output
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    main(packet_dir, manifest_path)
