import json
import os
import sys
from datetime import datetime
from pathlib import Path

def load_json_file(file_path):
    """Load JSON data from a file."""
    with open(file_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def parse_date(date_str):
    """Parse a date string to datetime object, handling None and empty strings."""
    if not date_str:
        return None
    try:
        # Handle potential time part
        if ' ' in date_str:
            date_str = date_str.split(' ')[0]
        return datetime.strptime(date_str, '%Y-%m-%d')
    except (ValueError, TypeError):
        return None

def extract_fact_value(award, fact_name, rule_id):
    """Extract the value for a specific fact from an award based on the rule."""
    if rule_id == "usa.period_3y":
        if fact_name == "performance start":
            date_str = award.get("period_of_performance", {}).get("start_date")
            return date_str, "usaspending_awards"
        elif fact_name == "performance end":
            date_str = award.get("period_of_performance", {}).get("end_date")
            return date_str, "usaspending_awards"
    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            value = award.get("total_obligation")
            # Convert to string if numeric, keep None if null
            if value is not None:
                # Format as decimal string without extra formatting
                return str(value), "usaspending_awards"
            return None, "usaspending_awards"
        elif fact_name == "potential value":
            value = award.get("base_and_all_options")
            if value is not None:
                return str(value), "usaspending_awards"
            return None, "usaspending_awards"
    return None, None

def process_packet(packet_dir, manifest):
    """Process the packet directory and manifest to extract facts."""
    # Load the awards data
    awards_file = Path(packet_dir) / "usaspending_awards.json"
    if not awards_file.exists():
        raise FileNotFoundError(f"File not found: {awards_file}")

    awards_data = load_json_file(awards_file)

    # Create a mapping from generated_unique_award_id to award
    awards_map = {}
    for award in awards_data:
        award_id = award.get("generated_unique_award_id")
        if award_id:
            awards_map[award_id] = award

    # Prepare result structure
    result = {}

    # Process each pair in the manifest
    for pair in manifest["pairs"]:
        rule_id, entity_id = pair.split("::", 1)

        if entity_id not in awards_map:
