                if source.endswith('.json'):
                    source = source[:-5]
                pair_result[fact_name] = [value, source]

        result[pair] = pair_result

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

